public class Ex09EmbeddedContainerLifecycle {
    public static void main(String[] args) {
        String[] steps = {
            "refreshContext()",
            "  onRefresh(): createWebServer()",
            "    new Tomcat(): bind port / context path",
            "    Tomcat.start(): accept connections",
            "  finishRefresh(): publish ApplicationReadyEvent",
            "  registerShutdownHook(): graceful stop on exit"
        };
        System.out.println("embedded container startup sequence:");
        for (int i = 0; i < steps.length; i++) System.out.println("  " + (i + 1) + ". " + steps[i]);
        System.out.println("port bound before ApplicationReadyEvent = true");
    }
}
